/**
 * @dotmix/cli — sibling stylesheets generated by `mix create` and `mix add`.
 * A component `UserCard.tix` gets `UserCard.<ext>`, imported first by the component.
 */

export type StylesheetFormat = "scss" | "sass" | "less" | "pcss" | "css";

export interface StylesheetRule {
  readonly selector: string;
  readonly declarations: ReadonlyArray<readonly [property: string, value: string]>;
}

/** Renders rules in the syntax of the format (the indented syntax for .sass, braces otherwise). */
export function renderStylesheet(format: StylesheetFormat, rules: readonly StylesheetRule[]): string {
  return rules
    .map((rule) => {
      if (format === "sass") {
        const body = rule.declarations.map(([property, value]) => `  ${property}: ${value}`).join("\n");
        return `${rule.selector}\n${body}\n`;
      }
      const body = rule.declarations.map(([property, value]) => `  ${property}: ${value};`).join("\n");
      return `${rule.selector} {\n${body}\n}\n`;
    })
    .join("\n");
}

/** The import line a component uses for its sibling stylesheet. */
export function stylesheetImportLine(componentBaseName: string, format: StylesheetFormat): string {
  return `import "./${componentBaseName}.${format}";\n`;
}
